function renderScore(){
  let card=$("v2-score-card");
  if(!card){
    card=node("section",undefined,"v2-score-card");
    card.id="v2-score-card";
    document.querySelector(".toolbar").insertAdjacentElement("afterend",card);
  }
  card.hidden=state.overview;
  const scoring=state.data?.front_v2_scores,item=scoring?.items?.[state.module];
  card.replaceChildren();
  if(!item?.score_valid){
    card.append(node("strong","正面V2评分暂不可用"),node("span","当前结果没有通过稳定版评分接线。","muted"));
    return;
  }
  const heading=node("div",undefined,"score-heading");
  heading.append(node("span","正面正式评分","score-kicker"),node("strong",item.score.toFixed(1),"score-number"),node("span","分","score-unit"));
  const component=item.score_kind==="v2_pigmentation_component";
  if(component)heading.querySelector(".score-kicker").textContent="正面分项评分";
  const grade=node("span",component?"V2子分":item.severity,"score-grade");
  grade.dataset.grade=item.severity;
  const copy=node("div",undefined,"score-copy");
  copy.append(grade,node("p",item.word_item+" · 分数越高表示当前图像中相关表现越明显。"));
  if(state.module==="spots"||state.module==="brown"){
    const combined=scoring.pigmentation_composite;
    if(combined)copy.append(node("p","综合色素参考："+combined.score.toFixed(1)+"分 · "+combined.severity+"（综合程度）","muted"));
    copy.append(node("p",scoring.notes?.pigmentation,"muted"));
  }
  card.append(heading,copy);
}
