"""Loopback-only local service. One worker owns the reusable model session."""
import argparse, base64, json, threading, uuid, re, shutil, zipfile
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import FileResponse, HTMLResponse
from starlette.concurrency import run_in_threadpool
from starlette.background import BackgroundTask
import uvicorn
from shuiguang.config import ROOT,VIEWS
from shuiguang.io import write_json,read_image,write_image,sha256,contained

app=FastAPI(docs_url=None,redoc_url=None)
executor=ThreadPoolExecutor(max_workers=1)
lock=threading.Lock();jobs={};session=None;device="cpu";busy=False
from shuiguang.camera_core.service import CaptureService
from shuiguang.camera_core.routes import register as register_capture
capture_service=CaptureService(lambda:ROOT,lambda:busy)
register_capture(app,capture_service)

def camera_job_status(jid):
 if jid in jobs:return jobs[jid]['status']
 if (ROOT/'runtime/jobs'/jid/'error.json').is_file():return 'failed'
 if (ROOT/'outputs'/jid/'运行回执.json').is_file():
  r=json.loads((ROOT/'outputs'/jid/'运行回执.json').read_text(encoding='utf-8'))
  return 'complete' if r.get('status') in ('success','partial_success') else 'failed'
 return 'failed'

def enqueue_camera(s,source):
 global busy
 with lock:
  if busy:raise HTTPException(409,'已有检测任务正在运行')
  busy=True
 try:
  jid=uuid.uuid4().hex;folder=ROOT/'runtime/jobs'/jid;folder.mkdir(parents=True)
  manifest={'schema_version':'shuiguang_capture_v1','capture_id':jid,'subject_id':'','modality':'RGB',
     'acquisition':{'session_id':s['session_id'],'revision':s['revision'],'config':s['config']},'views':{}}
  for view in VIEWS:
   photo=s['photos'][view];path=folder/(view+'.jpg');shutil.copyfile(source/photo['filename'],path)
   if sha256(path)!=photo['sha256']:raise ValueError('采集快照校验失败')
   manifest['views'][view]={k:v for k,v in photo.items() if k not in ('filename','image_url')}
   manifest['views'][view]['path']=path.name
  save=folder/'capture.json';write_json(save,manifest)
  jobs[jid]={'id':jid,'status':'running','progress':{'completed':0,'total':24}}
  executor.submit(work,jid,save)
  return jid
 except Exception:
  with lock:busy=False
  raise

def work(job_id,manifest):
 global session,busy
 try:
  from shuiguang.capture import load_capture
  load_capture(manifest)
  if session is None:
   from shuiguang.runtime import configure
   configure(device)
   from shuiguang.pipeline import AnalysisSession
   session=AnalysisSession(device)
  def progress(event): jobs[job_id]["progress"]=event
  result,status=session.analyze(manifest,ROOT/"outputs",progress)
  jobs[job_id].update(status="complete",analysis_status=status,base="/results/"+result.name+"/")
 except Exception as exc:
  write_json(ROOT/"runtime/jobs"/job_id/"error.json",{"type":type(exc).__name__,"message":str(exc)})
  jobs[job_id].update(status="failed",message="检测未完成，请核对输入或查看运行回执")
 finally:
  with lock: busy=False

@app.get("/health")
def health():
 return {"status":"ok","product":"shuiguang","version":"0.0.1","device":device,"busy":busy}

async def upload_json(request):
 size=request.headers.get("content-length","")
 if not size.isdigit() or int(size)>52*1024*1024:raise HTTPException(413,"上传大小超限")
 body=await request.body()
 if len(body)>52*1024*1024:raise HTTPException(413,"上传大小超限")
 try:
  value=json.loads(body)
  if not isinstance(value,dict):raise ValueError()
  return value
 except (ValueError,TypeError):raise HTTPException(400,"无法读取上传数据")

@app.post("/api/imports")
async def import_photos(request:Request):
 from shuiguang.orientation import inspect_photos
 from PIL import Image
 from io import BytesIO
 data=await upload_json(request)
 photos=data.get("photos",[])
 if not isinstance(photos,list) or len(photos)!=3:raise HTTPException(400,"请一次选择三张RGB照片")
 if type(data.get("mirrored",False)) is not bool:raise HTTPException(400,"镜像选项无效")
 iid=uuid.uuid4().hex;folder=ROOT/"runtime/imports"/iid;folder.mkdir(parents=True)
 paths=[];info=[]
 try:
  for i,photo in enumerate(photos):
   encoded=photo["data"]
   if len(encoded)>17*1024*1024:raise ValueError("单张照片不能超过12MB")
   content=base64.b64decode(encoded,validate=True)
   if len(content)>12*1024*1024:raise ValueError("单张照片不能超过12MB")
   with Image.open(BytesIO(content)) as im:
    if im.mode not in {"RGB","RGBA"}:raise ValueError("需要彩色RGB照片")
   original=folder/(str(i)+".upload");original.write_bytes(content)
   image=read_image(original,data.get("mirrored",False))
   path=folder/(str(i)+".png");write_image(path,image);paths.append(path)
   info.append({"index":i,"name":str(photo.get("name",f"照片{i+1}"))[:120],
      "preview":f"/api/imports/{iid}/{i}.png","sha256":sha256(path)})
  if len({r["sha256"] for r in info})!=3:raise ValueError("三张照片不能重复")
 except Exception as exc:
  message=str(exc) if isinstance(exc,ValueError) else "图片无法读取，请选择三张有效的RGB照片"
  raise HTTPException(400,message) from exc
 try:orientation=await run_in_threadpool(inspect_photos,paths)
 except ValueError as exc:raise HTTPException(400,str(exc)) from exc
 result={"import_id":iid,"photos":info,**orientation,"mirrored_corrected":data.get("mirrored",False)}
 write_json(folder/"import.json",result)
 return result

@app.get("/api/imports/{import_id}/{name}")
def import_preview(import_id:str,name:str):
 if not re.fullmatch("[a-f0-9]{32}",import_id) or name not in {"0.png","1.png","2.png"}:raise HTTPException(404)
 return safe_file(ROOT/"runtime/imports"/import_id,name)

@app.post("/api/jobs",status_code=202)
async def submit(request:Request):
 global busy
 if request.headers.get("content-type","").split(";")[0]!="application/json": raise HTTPException(415,"需要JSON三视图")
 size=request.headers.get("content-length")
 if not size or not size.isdigit() or int(size)>52*1024*1024: raise HTTPException(413,"上传大小超限")
 body=await request.body()
 if len(body)>52*1024*1024:raise HTTPException(413,'上传大小超限')
 try:incoming=json.loads(body)
 except ValueError:raise HTTPException(400,'请求不是有效JSON')
 if not isinstance(incoming,dict):raise HTTPException(400,'请求必须为JSON对象')
 if 'capture_session_id' in incoming:
