  _,_,view=max(candidates,key=lambda row:(row[0],row[1],-VIEWS.index(row[2])))
  output[region]={"view":view,"modules":{
    name:item.get("regions",{}).get(region,{"status":"unavailable"})
    for name,item in views[view].get("modules",{}).items()}}
 return output

