    frozen=load(c/"frozen_inputs_r1/freeze_manifest.json")
    receipt=load(c/"frozen_inputs_r1/FREEZE_COMPLETE.json")
    assert sha(c/"frozen_inputs_r1/freeze_manifest.json")==receipt["files"]["freeze_manifest.json"]
    people=frozen["inputs"]
    assert Counter(p["split"] for p in people)=={"development":800,"independent_confirmation":200}
    assert len({p["input_sha256"] for p in people})==1000
