        p=c/name/"index.json"
        indices[name]={x["input_sha256"]:x for x in load(p)}
    rows=[]
    for person in people:
        digest=person["input_sha256"]
        sources=[]
        raw={name:[] for name in ("pores","spots","surface_gloss","brown","uv_spots")}
        for kind,index in indices.items():
            entry=index.get(digest,{})
            if not entry.get("scoring_root"):continue
            root=Path(entry["scoring_root"])
            if not root.resolve().is_relative_to(c):raise ValueError("Unexpected evidence root")
            datafile=root/"result.json"
            if datafile.is_file():
                payload=load(datafile)
                input_sha=payload.get("input_sha256")
                if isinstance(input_sha,dict):input_sha=input_sha.get("RGB_M")
                assert input_sha==digest, "cohort input identity mismatch"
                for name in raw:
                    hits=list(root.rglob("doctor_v3_"+name+".npz"))
                    raw[name].extend(str(p) for p in hits if p.with_suffix(".json").is_file())
                sources.append({"kind":kind,"result_sha256":sha(datafile),"path":str(datafile)})
        rows.append({"subject_id":person["source_subject_id"],"split":person["split"],"input_sha256":digest,
                     "sources":sources,"spatial_evidence":raw,
                     "can_repartition_three":all(raw[n] for n in ("pores","spots","surface_gloss"))})
    counts={n:sum(bool(r["spatial_evidence"][n]) for r in rows) for n in raw}
    result={"status":"ready" if all(r["can_repartition_three"] for r in rows) else "missing_spatial_evidence",
        "cohort_counts":dict(Counter(p["split"] for p in people)),"checked_samples":len(rows),
        "samples_with_spatial_evidence":counts,
        "scope":"three explicit saved result chains: roi repair, parameter replay, original terminal index",
        "source_manifest_sha256":sha(c/"frozen_inputs_r1/freeze_manifest.json"),
        "reason":"Existing regional aggregates do not preserve the masks, coordinates and pixel distributions needed for water coarse ROIs.",
        "detector_inference_executed":False,"original_images_read":False,
        "rows":rows}
